const placementRaycaster=new THREE.Raycaster(),placementPointer=new THREE.Vector2();
function placementError(x,z,kind){
 if(Math.abs(x)>98||Math.abs(z)>98)return"Escolha um ponto dentro do vale.";
 if(Math.hypot(x-48,z+82)<28)return"Este local fica muito perto da Vila Vizinha. Afaste-se para construir sua própria vila.";
 if(riverDistance(x,z)<9)return kind==="campfire"?"Não é seguro colocar a fogueira tão perto do rio.":"Este ponto fica muito perto do rio.";
 if(kind==="field"){for(const [dx,dz] of [[-2,0],[2,0],[0,-1.6],[0,1.6]])if(Math.abs(groundHeight(x+dx,z+dz)-groundHeight(x,z))>.8)return"Escolha uma área mais plana para preparar o canteiro.";return"";}
 if(kind==="campfire"){
  if(placedCampfires.some(f=>Math.hypot(f.position.x-x,f.position.z-z)<3.5))return"Escolha um local mais distante de outra fogueira.";
 }else if(kind==="chest"){
  if(placedStorageChests.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<3.5))return"Afaste o baú de outro baú.";
  if(placedShelters.some(h=>Math.hypot(h.position.x-x,h.position.z-z)<3.5))return"Afaste o baú do abrigo.";
  if(placedWorkbenches.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<3.5))return"Afaste o baú da bancada.";
  if(placedCarpentryShops.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<4))return"Afaste o baú da oficina.";
  if(placedCampfires.some(f=>Math.hypot(f.position.x-x,f.position.z-z)<3.5))return"Afaste o baú da fogueira.";
 }else if(kind==="workbench"){
  if(placedWorkbenches.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<4))return"Afaste a bancada de outra bancada.";
  if(placedShelters.some(h=>Math.hypot(h.position.x-x,h.position.z-z)<5))return"Afaste a bancada do abrigo.";
  if(placedCampfires.some(f=>Math.hypot(f.position.x-x,f.position.z-z)<4))return"Afaste a bancada da fogueira.";
 }else{
  if(placedCarpentryShops.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<7))return"Afaste a construção da oficina de carpintaria.";
  if(placedShelters.some(h=>Math.hypot(h.position.x-x,h.position.z-z)<7))return"Afaste o abrigo de outra construção.";
  if(placedWorkbenches.some(b=>Math.hypot(b.position.x-x,b.position.z-z)<4))return"Afaste o abrigo da bancada.";
  if(placedCampfires.some(f=>Math.hypot(f.position.x-x,f.position.z-z)<4))return"Afaste o abrigo da fogueira.";
 }
 for(const [dx,dz] of [[-2.8,0],[2.8,0],[0,-2.5],[0,2.5],[-2,-2],[2,-2],[-2,2],[2,2]])if(Math.abs(groundHeight(x+dx,z+dz)-groundHeight(x,z))>.8)return"Este ponto é muito inclinado. Escolha um terreno mais plano.";
 return"";
}
function canBuildShelter(){return state.inventory.wood>=12&&state.inventory.branches>=8&&state.inventory.fiber>=6;}
function canBuildWorkbench(){return state.inventory.wood>=8&&state.inventory.branches>=6&&state.inventory.stones>=4;}
function canBuildCarpentry(){return state.inventory.wood>=16&&state.inventory.branches>=10&&state.inventory.stones>=8&&state.inventory.fiber>=6;}
function canBuildChest(){return state.inventory.planks>=6&&state.inventory.beams>=2;}
function startPlacement(kind){
 if(kind==="campfire"&&state.items.campfires<1)return;
 if(kind==="shelter"&&!canBuildShelter()){craftStatus.textContent="Materiais necessários: 12 madeiras, 8 galhos e 6 fibras.";return;}
 if(kind==="workbench"&&!canBuildWorkbench()){craftStatus.textContent="Materiais necessários para a bancada: 8 madeiras, 6 galhos e 4 pedras.";return;}
 if(kind==="carpentry"&&!canBuildCarpentry()){craftStatus.textContent="Materiais necessários para a oficina: 16 madeiras, 10 galhos, 8 pedras e 6 fibras.";return;}
 if(kind==="chest"&&!canBuildChest()){craftStatus.textContent="Para construir o baú, reúna 6 tábuas e 2 vigas na carpintaria.";return;}if(kind==="field"&&!state.tools.hoe){craftStatus.textContent="Fabrique uma enxada rudimentar para preparar a terra.";return;}
 selectedPlacementKind=kind;placementRotation=0;placementMode=true;placementFollow=true;pendingPlacement=null;placementPreview.visible=false;
 if(activeShelterPreview){scene.remove(activeShelterPreview);activeShelterPreview=null;}
 if(kind==="shelter"||kind==="workbench"||kind==="carpentry"||kind==="chest"||kind==="field"){
  activeShelterPreview=kind==="shelter"?buildShelter(0,0,0,true):kind==="workbench"?buildWorkbench(0,0,0,true):kind==="carpentry"?buildCarpentryShop(0,0,0,true):kind==="field"?buildField(0,0,0,true):buildStorageChest(0,0,0,true);activeShelterPreview.visible=false;root.classList.add("placing-shelter");
  // Procura um ponto válido a pelo menos 8 m do jogador, priorizando a direção para a qual ele olha.
  const forwardX=-Math.sin(player.yaw),forwardZ=-Math.cos(player.yaw);
  let candidate=null,bestScore=Infinity,farthest=null,farthestDistance=-1;placementDistance=0;
  const consider=(point)=>{
   if(placementError(point.x,point.z,kind))return;
   const dx=point.x-player.x,dz=point.z-player.z,distance=Math.hypot(dx,dz);
   if(distance>farthestDistance){farthest={...point};farthestDistance=distance;}
   if(distance<7)return;
   const forwardDot=distance>0?(dx*forwardX+dz*forwardZ)/distance:0;
   const score=Math.abs(distance-8.5)+Math.max(0,.15-forwardDot)*12;
   if(score<bestScore){candidate={...point};bestScore=score;placementDistance=distance;}
  };
  for(let d=7;d<=10;d+=1)for(let ix=-5;ix<=5;ix++)for(let iz=-5;iz<=5;iz++){
   consider({x:clamp(player.x+forwardX*d+ix*.7,-96,96),z:clamp(player.z+forwardZ*d+iz*.7,-96,96)});
  }
  if(!candidate&&farthest){candidate=farthest;placementDistance=farthestDistance;}
  if(candidate){
   pendingPlacement={x:Math.round(candidate.x*10)/10,z:Math.round(candidate.z*10)/10};
   activeShelterPreview.position.set(pendingPlacement.x,groundHeight(pendingPlacement.x,pendingPlacement.z),pendingPlacement.z);
   activeShelterPreview.rotation.y=placementRotation;activeShelterPreview.visible=true;
  }
 }
 craftVisible=false;craftPanel.hidden=true;placementPrompt.hidden=false;root.classList.add("placing-structure");
 placementHint.textContent=kind==="field"?(pendingPlacement?"Prévia do canteiro posicionada. Ajuste e confirme.":"Mova-se para uma área plana do vale."):kind==="shelter"?(pendingPlacement?"Prévia do abrigo posicionada. Use o joystick ou toque no chão para ajustar.":"Mova-se para uma área livre do vale."):kind==="workbench"?(pendingPlacement?"Prévia da bancada posicionada. Use o joystick ou toque no chão para ajustar.":"Mova-se para uma área livre do vale."):kind==="carpentry"?(pendingPlacement?"Prévia da oficina de carpintaria posicionada. Ajuste e confirme.":"Mova-se para uma área livre do vale."):kind==="chest"?(pendingPlacement?"Prévia do baú posicionada. Ajuste a rotação e confirme.":"Mova-se para uma área livre do vale."):"Toque no terreno para pré-visualizar a fogueira."
 placementConfirm.disabled=!pendingPlacement;document.exitPointerLock?.();keys.clear();resetStick();
}
function cancelPlacement(){placementMode=false;placementFollow=false;pendingPlacement=null;selectedPlacementKind=null;placementPreview.visible=false;if(activeShelterPreview){scene.remove(activeShelterPreview);activeShelterPreview=null;}placementPrompt.hidden=true;root.classList.remove("placing-structure","placing-shelter");}
function selectPlacementPoint(clientX,clientY){if(!placementMode)return;const rect=renderer.domElement.getBoundingClientRect();placementPointer.set((clientX-rect.left)/rect.width*2-1,-((clientY-rect.top)/rect.height)*2+1);placementRaycaster.setFromCamera(placementPointer,camera);const hit=placementRaycaster.intersectObject(terrainMesh,false)[0];if(!hit){placementHint.textContent="Toque em uma parte visível do chão do vale.";placementConfirm.disabled=true;return;}const x=hit.point.x,z=hit.point.z,reason=placementError(x,z,selectedPlacementKind);if(reason){pendingPlacement=null;placementPreview.visible=false;if(activeShelterPreview)activeShelterPreview.visible=false;placementConfirm.disabled=true;placementHint.textContent=reason;return;}placementFollow=false;pendingPlacement={x:Math.round(x*10)/10,z:Math.round(z*10)/10};if(selectedPlacementKind==="campfire"){placementPreview.position.set(pendingPlacement.x,groundHeight(pendingPlacement.x,pendingPlacement.z)+.05,pendingPlacement.z);placementPreview.visible=true;}else if(activeShelterPreview){activeShelterPreview.position.set(pendingPlacement.x,groundHeight(pendingPlacement.x,pendingPlacement.z),pendingPlacement.z);activeShelterPreview.rotation.y=placementRotation;activeShelterPreview.visible=true;}placementConfirm.disabled=false;placementHint.textContent="Prévia posicionada. Confirme para construir ou gire para ajustar.";}
function updateShelterPreviewFromPlayer(){
 if(!placementMode||!(selectedPlacementKind==="shelter"||selectedPlacementKind==="workbench"||selectedPlacementKind==="carpentry"||selectedPlacementKind==="chest"||selectedPlacementKind==="field")||!placementFollow||!activeShelterPreview)return;
 const fx=-Math.sin(player.yaw),fz=-Math.cos(player.yaw);
 let best=null,bestScore=Infinity;
 for(let d=7;d<=10;d+=1){
  const baseX=clamp(player.x+fx*d,-96,96),baseZ=clamp(player.z+fz*d,-96,96);
  for(let ix=-2;ix<=2;ix++)for(let iz=-2;iz<=2;iz++){
   const x=clamp(baseX+ix*.65,-96,96),z=clamp(baseZ+iz*.65,-96,96);
   if(placementError(x,z,selectedPlacementKind))continue;
   const dist=Math.hypot(x-player.x,z-player.z),dot=dist>0?((x-player.x)*fx+(z-player.z)*fz)/dist:0;
   const score=Math.abs(dist-8.5)+Math.max(0,.2-dot)*8;
   if(score<bestScore){bestScore=score;best={x,z};}
  }
  if(best)break;
 }
 if(best){
  pendingPlacement={x:Math.round(best.x*10)/10,z:Math.round(best.z*10)/10};
  activeShelterPreview.position.set(pendingPlacement.x,groundHeight(pendingPlacement.x,pendingPlacement.z),pendingPlacement.z);
  activeShelterPreview.rotation.y=placementRotation;activeShelterPreview.visible=true;placementConfirm.disabled=false;
  placementHint.textContent=selectedPlacementKind==="field"?"A prévia do canteiro acompanha seu movimento. Toque no chão para fixar e confirme.":selectedPlacementKind==="workbench"?"A prévia da bancada acompanha seu movimento. Toque no chão para fixar e gire antes de confirmar.":"A prévia acompanha seu movimento. Agora você pode construir em qualquer área livre do vale, longe da Vila Vizinha.";
 }else{placementConfirm.disabled=true;placementHint.textContent="Mova-se para uma área livre do vale, mantendo distância da Vila Vizinha e do rio.";}
}
function confirmPlacement(){
 if(!placementMode||!pendingPlacement)return;
 const reason=placementError(pendingPlacement.x,pendingPlacement.z,selectedPlacementKind);if(reason){placementHint.textContent=reason;return;}
 const pos={...pendingPlacement},builtKind=selectedPlacementKind;
 if(builtKind==="campfire"){if(state.items.campfires<1)return;placedCampfires.push(buildCampfire(pos.x,pos.z));state.campfires=state.campfires||[];state.campfires.push(pos);state.items.campfires--;notify("Fogueira colocada no local escolhido.");}
 else if(builtKind==="shelter"){if(!canBuildShelter())return;state.inventory.wood-=12;state.inventory.branches-=8;state.inventory.fiber-=6;const built={x:pos.x,z:pos.z,rotation:placementRotation};state.shelters.push(built);placedShelters.push(buildShelter(built.x,built.z,built.rotation,false));notify("Seu primeiro abrigo foi construído!");objective.querySelector("strong").textContent="Primeiro abrigo construído";objective.querySelector("p").textContent="Você ergueu seu primeiro abrigo com os materiais que reuniu. Sua vila começou a tomar forma.";}
 else if(builtKind==="field"){if(!state.tools.hoe)return;const data={x:pos.x,z:pos.z,rotation:placementRotation,plantedDay:null};state.fields.push(data);const group=buildField(data.x,data.z,data.rotation,false);placedFields.push({data,group,stage:0,crops:null});notify("Canteiro preparado. Agora você pode plantar sementes de trigo.");}
 else if(builtKind==="workbench"){if(!canBuildWorkbench())return;state.inventory.wood-=8;state.inventory.branches-=6;state.inventory.stones-=4;const built={x:pos.x,z:pos.z,rotation:placementRotation};state.workbenches.push(built);placedWorkbenches.push(buildWorkbench(built.x,built.z,built.rotation,false));notify("Sua primeira bancada de fabricação foi construída!");objective.querySelector("strong").textContent="Bancada de fabricação construída";objective.querySelector("p").textContent="Agora você tem um espaço de trabalho para aprender a fabricar equipamentos melhores.";}else if(builtKind==="chest"){if(!canBuildChest())return;state.inventory.planks-=6;state.inventory.beams-=2;const built={x:pos.x,z:pos.z,rotation:placementRotation,inventory:{branches:0,stones:0,fiber:0,wood:0,planks:0,beams:0}};state.storageChests.push(built);placedStorageChests.push(buildStorageChest(built.x,built.z,built.rotation,false));notify("Baú de armazenamento construído!");objective.querySelector("strong").textContent="Baú de armazenamento construído";objective.querySelector("p").textContent="Agora você pode guardar e retirar os materiais que reuniu pelo vale.";}else{if(!canBuildCarpentry())return;state.inventory.wood-=16;state.inventory.branches-=10;state.inventory.stones-=8;state.inventory.fiber-=6;const built={x:pos.x,z:pos.z,rotation:placementRotation};state.carpentryShops.push(built);placedCarpentryShops.push(buildCarpentryShop(built.x,built.z,built.rotation,false));notify("Sua oficina de carpintaria foi construída!");objective.querySelector("strong").textContent="Oficina de carpintaria construída";objective.querySelector("p").textContent="Agora você pode transformar madeira bruta em peças para as próximas construções.";}
 saveState();cancelPlacement();renderCrafting();craftStatus.textContent=builtKind==="shelter"?"Abrigo construído no local escolhido.":builtKind==="workbench"?"Bancada de fabricação construída no local escolhido.":builtKind==="carpentry"?"Oficina de carpintaria construída no local escolhido.":builtKind==="chest"?"Baú construído no local escolhido.":"Fogueira colocada no local escolhido.";
}
const recipes={axe:{label:"Machado rudimentar",cost:{branches:3,stones:2,fiber:2}},pickaxe:{label:"Picareta rudimentar",cost:{branches:3,stones:3,fiber:2}},spear:{label:"Lança rudimentar",cost:{branches:3,stones:2,fiber:2}},hoe:{label:"Enxada rudimentar",cost:{branches:3,stones:2,fiber:2}},torch:{label:"Tocha",cost:{branches:1,fiber:2}},campfire:{label:"Fogueira",cost:{branches:5,stones:4}}};
function canCraft(key){const r=recipes[key];return Object.entries(r.cost).every(([k,v])=>state.inventory[k]>=v)&&(key!=="axe"||!state.tools.axe)&&(key!=="pickaxe"||!state.tools.pickaxe)&&(key!=="spear"||!state.tools.spear)&&(key!=="hoe"||!state.tools.hoe);}
function nearWorkbench(){return placedWorkbenches.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<7);}
const advancedRecipes={axe:{label:"Machado reforçado",cost:{wood:5,stones:5,branches:4,fiber:3}},pickaxe:{label:"Picareta reforçada",cost:{wood:4,stones:7,branches:4,fiber:3}}};
function canCraftAdvanced(key){const r=advancedRecipes[key];return nearWorkbench()&&state.tools[key]&&!state.tools[key+"Advanced"]&&Object.entries(r.cost).every(([k,v])=>state.inventory[k]>=v);}
const carpentryPanel=document.getElementById("carpentry-panel"),carpentryInventory=document.getElementById("carpentry-inventory"),carpentryStatus=document.getElementById("carpentry-status");
const storagePanel=document.getElementById("storage-panel"),storageSelect=document.getElementById("storage-resource"),storageAmount=document.getElementById("storage-amount"),storageInventory=document.getElementById("storage-inventory"),storageStatus=document.getElementById("storage-status");let activeStorageChest=null;const storageLabels={branches:"Galhos",stones:"Pedras",fiber:"Fibras",wood:"Madeira bruta",planks:"Tábuas",beams:"Vigas",berries:"Bagas silvestres",meals:"Refeições cozidas",meat:"Carne crua",hide:"Couro",wheatSeeds:"Sementes de trigo",wheat:"Trigo colhido"};
function openCooking(){cookingPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderCooking();cookStatus.textContent="Use bagas e um galho para preparar uma refeição na fogueira."; }
function renderCooking(){const cook=document.getElementById("cook-meal"),cookMeat=document.getElementById("cook-meat"),eat=document.getElementById("eat-meal");if(cook)cook.disabled=state.inventory.berries<2||state.inventory.branches<1;if(cookMeat)cookMeat.disabled=state.inventory.meat<1||state.inventory.branches<1;if(eat)eat.disabled=state.inventory.meals<1||state.hunger>=100;document.getElementById("cook-inventory").textContent="Bagas: "+state.inventory.berries+" · Galhos: "+state.inventory.branches+" · Carne: "+state.inventory.meat+" · Refeições prontas: "+state.inventory.meals+" · Fome: "+Math.round(state.hunger)+"%";}
document.getElementById("cooking-close").addEventListener("click",()=>{cookingPanel.hidden=true;});
document.getElementById("cook-meat").addEventListener("click",()=>{if(state.inventory.meat<1||state.inventory.branches<1){cookStatus.textContent="Falta 1 carne e 1 galho para assar a carne.";return;}state.inventory.meat--;state.inventory.branches--;state.inventory.meals++;saveState();cookStatus.textContent="Carne assada preparada! Ela pode ser consumida ou guardada.";notify("Carne assada preparada.");renderCooking();renderCrafting();});
document.getElementById("cook-meal").addEventListener("click",()=>{if(state.inventory.berries<2||state.inventory.branches<1){cookStatus.textContent="Faltam 2 bagas e 1 galho para preparar a refeição.";return;}state.inventory.berries-=2;state.inventory.branches--;state.inventory.meals++;saveState();cookStatus.textContent="Refeição preparada! Você pode comê-la agora ou guardar para depois.";notify("Refeição cozida preparada.");renderCooking();renderCrafting();});
