function renderCrafting(){const shelterButton=craftPanel.querySelector("[data-build-shelter]");if(shelterButton)shelterButton.disabled=!canBuildShelter();const workbenchButton=craftPanel.querySelector("[data-build-workbench]");if(workbenchButton)workbenchButton.disabled=!canBuildWorkbench();const carpentryButton=craftPanel.querySelector("[data-build-carpentry]");if(carpentryButton)carpentryButton.disabled=!canBuildCarpentry();const chestBuildButton=craftPanel.querySelector("[data-build-chest]");if(chestBuildButton)chestBuildButton.disabled=!canBuildChest();const fieldButton=craftPanel.querySelector("[data-build-field]");if(fieldButton)fieldButton.disabled=!state.tools.hoe;inventoryText.textContent="Bagas: "+state.inventory.berries+"   Galhos: "+state.inventory.branches+"   Pedras: "+state.inventory.stones+"   Fibras: "+state.inventory.fiber+"   Madeira: "+state.inventory.wood+"   Carne: "+state.inventory.meat+"   Couro: "+state.inventory.hide+"   Sementes: "+state.inventory.wheatSeeds+"   Trigo: "+state.inventory.wheat+"\\nEnxada: "+(state.tools.hoe?"fabricada":"não fabricada")+"   Lança: "+(state.tools.spear?"fabricada":"não fabricada")+"   Machado: "+(state.tools.axeAdvanced?"reforçado":state.tools.axe?"rudimentar":"não fabricado")+"   Picareta: "+(state.tools.pickaxeAdvanced?"reforçada":state.tools.pickaxe?"rudimentar":"não fabricada")+"\\nTochas: "+state.items.torches+"   Fogueiras: "+state.items.campfires;craftPanel.querySelectorAll("[data-craft]").forEach(btn=>{const key=btn.dataset.craft;btn.disabled=!canCraft(key);});campfirePlace.hidden=state.items.campfires<1;const eatBerries=document.getElementById("eat-berries");if(eatBerries)eatBerries.disabled=state.inventory.berries<1||state.hunger>=100;const hungerCraft=document.getElementById("hunger-craft-status");if(hungerCraft)hungerCraft.textContent="Fome: "+Math.round(state.hunger)+"% · Bagas: "+state.inventory.berries+" · Refeições: "+state.inventory.meals;}
