function rotateShelter(delta){if(!placementMode||!(selectedPlacementKind==="shelter"||selectedPlacementKind==="workbench"||selectedPlacementKind==="carpentry"||selectedPlacementKind==="chest"||selectedPlacementKind==="field")||!activeShelterPreview)return;placementRotation=(placementRotation+delta+Math.PI*2)%(Math.PI*2);activeShelterPreview.rotation.y=placementRotation;}
function performGather(target){if(!target)return;if(target.kind==="field"){const entry=target.field;if(entry.data.plantedDay===null||entry.data.plantedDay===undefined){if(!state.tools.hoe){notify("Fabrique uma enxada para trabalhar a terra.");return;}if(state.inventory.wheatSeeds<1){notify("Você precisa encontrar sementes silvestres antes de plantar.");return;}state.inventory.wheatSeeds--;entry.data.plantedDay=state.day;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Trigo plantado. A colheita ficará pronta em 3 dias.");}else if(state.day-entry.data.plantedDay>=2){state.inventory.wheat+=5;state.inventory.wheatSeeds++;entry.data.plantedDay=null;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Colheita realizada: +5 trigo e +1 semente.");}else{const remaining=3-(state.day-entry.data.plantedDay);notify("O trigo ainda está crescendo. Faltam "+remaining+" dia(s) para a colheita.");}renderCrafting();return;}if(target.kind==="animal"){if(!state.tools.spear){notify("Você precisa fabricar uma lança rudimentar para caçar.");return;}const animal=target.animal;state.huntedAnimals=state.huntedAnimals.filter(v=>v.id!==animal.id);state.huntedAnimals.push({id:animal.id,day:state.day});animal.group.visible=false;animal.alive=false;state.inventory.meat+=2;state.inventory.hide+=1;notify("Caça realizada: +2 carnes e +1 couro.");saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="tree"){const index=target.index;setTreeVisible(index,false);state.felledTrees.push({index,day:state.day});const woodGain=state.tools.axeAdvanced?4:2,branchGain=state.tools.axeAdvanced?3:2;state.inventory.wood+=woodGain;state.inventory.branches+=branchGain;notify("Árvore cortada: +"+woodGain+" madeiras e +"+branchGain+" galhos.");}else{const node=target.node;if(node.type==="ore"&&!state.tools.pickaxe){notify("Você precisa de uma picareta para extrair este veio de pedra.");return;}if(node.type==="branch")state.inventory.branches+=node.amount;else if(node.type==="stone")state.inventory.stones+=node.amount;else if(node.type==="fiber")state.inventory.fiber+=node.amount;else if(node.type==="berry")state.inventory.berries+=node.amount;else if(node.type==="seed")state.inventory.wheatSeeds+=node.amount;else state.inventory.stones+=node.amount*(node.type==="ore"&&state.tools.pickaxeAdvanced?2:1);state.harvestedNodes[node.id]=state.day;node.group.visible=false;notify(node.type==="berry"?"Bagas silvestres coletadas: +"+node.amount+".":node.type==="seed"?"Sementes de trigo silvestre coletadas: +"+node.amount+".":node.type==="ore"?"Minério extraído: +"+node.amount+" pedras.":"Recursos coletados.");}saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;}
gatherButton.addEventListener("click",()=>performGather(currentGatherable));
