 renderer.domElement.addEventListener("click",e=>{if(placementMode){selectPlacementPoint(e.clientX,e.clientY);return;}if(benchVisible||craftVisible||dialogueOpen||!carpentryPanel.hidden||!storagePanel.hidden||!cookingPanel.hidden)return;const ndc=new THREE.Vector2((e.clientX/innerWidth)*2-1,-(e.clientY/innerHeight)*2+1),ray=new THREE.Raycaster();ray.setFromCamera(ndc,camera);const hits=ray.intersectObjects([...placedWorkbenches,...placedCarpentryShops,...placedStorageChests,...placedCampfires],true);if(hits.length){let o=hits[0].object;while(o&&o.parent!==scene)o=o.parent;const bench=placedWorkbenches.find(b=>b===o),shop=placedCarpentryShops.find(b=>b===o),chest=placedStorageChests.find(b=>b===o),fire=placedCampfires.find(b=>b===o);if(bench){if(Math.hypot(player.x-bench.position.x,player.z-bench.position.z)<7){openBench();return;}notify("Aproxime-se da bancada para utilizá-la.");return;}if(shop){if(Math.hypot(player.x-shop.position.x,player.z-shop.position.z)<8){openCarpentry();return;}notify("Aproxime-se da oficina de carpintaria para utilizá-la.");return;}if(chest){if(Math.hypot(player.x-chest.position.x,player.z-chest.position.z)<5){const index=placedStorageChests.indexOf(chest);openStorage(state.storageChests[index]);return;}notify("Aproxime-se do baú para guardar ou retirar materiais.");return;}if(fire){if(Math.hypot(player.x-fire.position.x,player.z-fire.position.z)<5){openCooking();return;}notify("Aproxime-se da fogueira para preparar alimentos.");return;}}if(!mobile&&state.started&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.();});document.addEventListener("mousemove",e=>{if(document.pointerLockElement!==renderer.domElement||!state.started)return;player.yaw-=e.movementX*.0022;player.pitch=clamp(player.pitch-e.movementY*.0018,-1.25,1.25);});
