 renderer.domElement.addEventListener("pointermove",e=>{if(e.pointerId!==lookPointer)return;const dx=e.clientX-lastLookX,dy=e.clientY-lastLookY;lastLookX=e.clientX;lastLookY=e.clientY;player.yaw-=dx*.004;player.pitch=clamp(player.pitch-dy*.003,-1.2,1.2);});const release=e=>{if(e.pointerId===lookPointer)lookPointer=null;};renderer.domElement.addEventListener("pointerup",release);renderer.domElement.addEventListener("pointercancel",release);
 function updateVillagers(dt,now){for(const villager of villagers){const target=villager.route[villager.index],dx=target[0]-villager.group.position.x,dz=target[1]-villager.group.position.z,dist=Math.hypot(dx,dz);if(dist<.45){villager.index=(villager.index+1)%villager.route.length;villager.walking=false;}else{villager.walking=true;const step=Math.min(dist,villager.speed*dt);villager.group.position.x+=dx/dist*step;villager.group.position.z+=dz/dist*step;villager.group.rotation.y=Math.atan2(dx,dz); }const swing=villager.walking?Math.sin(now*.009+villager.phase)*.42:Math.sin(now*.0015+villager.phase)*.025;villager.legs[0].rotation.x=swing;villager.legs[1].rotation.x=-swing;villager.group.position.y=groundHeight(villager.group.position.x,villager.group.position.z)+(villager.walking?Math.abs(Math.sin(now*.009+villager.phase))*.035:0);}}
 function frame(){requestAnimationFrame(frame);const now=performance.now(),dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;updateVillagers(dt,now);updateWildlife(dt,now);if(state.started){if(craftVisible||benchVisible||!carpentryPanel.hidden||!storagePanel.hidden||!cookingPanel.hidden){running=false;keys.clear();}const alinaDistance=Math.hypot(player.x-alinaX,player.z-alinaZ);let nearest=null,nearestDistance=4.6;if(!state.alinaTalked&&alinaDistance<=nearestDistance){nearest={id:"alina",name:"Alina · Anciã"};nearestDistance=alinaDistance;}for(const villager of villagers){const d=Math.hypot(player.x-villager.group.position.x,player.z-villager.group.position.z);if(d<nearestDistance){nearest={id:villager.id,name:villager.name};nearestDistance=d;}}currentInteractable=nearest;talkPrompt.hidden=dialogueOpen||craftVisible||benchVisible||!carpentryPanel.hidden||!storagePanel.hidden||placementMode||plotConfirm.hidden===false||!nearest;if(nearest)talkLabel.textContent=nearest.name.toUpperCase()+" ESTÁ POR PERTO";landPrompt.hidden=true;
let best=null,bestDist=3.5;for(const node of resourceNodes){const harvested=state.harvestedNodes[node.id];node.group.visible=harvested===undefined||state.day>=harvested+2;if(!node.group.visible)continue;const d=Math.hypot(player.x-node.x,player.z-node.z);if(d<bestDist&&!(node.type==="ore"&&!state.tools.pickaxe)){best={kind:"node",node};bestDist=d;}}for(const animal of wildlife){if(!animal.alive||!animal.group.visible)continue;const d=Math.hypot(player.x-animal.group.position.x,player.z-animal.group.position.z);if(d<bestDist){best={kind:"animal",animal};bestDist=d;}}for(const entry of placedFields){const d=Math.hypot(player.x-entry.data.x,player.z-entry.data.z);if(d<bestDist){best={kind:"field",field:entry};bestDist=d;}}if(state.tools.axe){treeSpots.forEach((tree,index)=>{if(state.felledTrees.some(entry=>entry.index===index))return;const d=Math.hypot(player.x-tree.x,player.z-tree.z);if(d<bestDist){best={kind:"tree",index};bestDist=d;}});}currentGatherable=best;gatherPrompt.hidden=dialogueOpen||craftVisible||benchVisible||!carpentryPanel.hidden||!storagePanel.hidden||placementMode||plotConfirm.hidden===false||!best;if(best)gatherLabel.textContent=best.kind==="animal"?(state.tools.spear?"COELHO SELVAGEM · CAÇAR":"COELHO SELVAGEM · FABRIQUE UMA LANÇA"):best.kind==="field"?(best.field.data.plantedDay===null||best.field.data.plantedDay===undefined?(state.inventory.wheatSeeds>0?"CANTEIRO · PLANTAR TRIGO":"CANTEIRO · ENCONTRE SEMENTES"):(state.day-best.field.data.plantedDay>=2?"TRIGO MADURO · COLHER":"TRIGO CRESCENDO")):best.kind==="tree"?"ÁRVORE PRONTA PARA CORTE":best.node.type==="ore"?"VEIO DE PEDRA · EXTRAIR":best.node.type==="branch"?"GALHOS CAÍDOS · COLETAR":best.node.type==="stone"?"PEDRAS SOLTAS · COLETAR":best.node.type==="berry"?"BAGAS SILVESTRES · COLETAR":"FIBRAS VEGETAIS · COLETAR";if(dialogueOpen||craftVisible||benchVisible||!carpentryPanel.hidden||!storagePanel.hidden||plotConfirm.hidden===false){running=false;keys.clear();moveX=0;moveZ=0;}marker.position.y=groundHeight(alinaX,alinaZ)+3.35+Math.sin(now*.0025)*.18;const forward=(keys.has("w")||keys.has("arrowup")?1:0)-(keys.has("s")||keys.has("arrowdown")?1:0)+moveZ,strafe=(keys.has("d")||keys.has("arrowright")?1:0)-(keys.has("a")||keys.has("arrowleft")?1:0)+moveX,mag=Math.hypot(forward,strafe);if(mag>.02){const speed=(running?8.1:5.2)*(state.hunger===0?.7:1),f=forward/Math.max(1,mag),s=strafe/Math.max(1,mag),dx=-Math.sin(player.yaw)*f+Math.cos(player.yaw)*s,dz=-Math.cos(player.yaw)*f-Math.sin(player.yaw)*s,nx=clamp(player.x+dx*speed*dt,-106,106),nz=clamp(player.z+dz*speed*dt,-106,106);if(riverDistance(nx,nz)>7.45||Math.abs(nz-BRIDGE_Z)<3.1){player.x=nx;player.z=nz;}else{if(riverDistance(nx,player.z)>7.45)player.x=nx;if(riverDistance(player.x,nz)>7.45)player.z=nz;}player.bob+=dt*(running?13:9)*Math.min(1,mag);}if(placementMode&&(selectedPlacementKind==="shelter"||selectedPlacementKind==="workbench"||selectedPlacementKind==="carpentry"||selectedPlacementKind==="chest"||selectedPlacementKind==="field")&&mag>.02)placementFollow=true;updateShelterPreviewFromPlayer();const bob=mag>.02?Math.sin(player.bob)*.035:0;camera.position.set(player.x,groundHeight(player.x,player.z)+eye+bob,player.z);camera.rotation.set(player.pitch,player.yaw,0);elapsedGame+=dt*(running?1.2:.72);if(elapsedGame>=1){const oldDay=state.day;updateClock(Math.floor(elapsedGame));elapsedGame%=1;if(state.day!==oldDay){refreshRegrowth();for(const entry of placedFields)refreshFieldVisual(entry);saveState();}}if(now-lastSave>4000){state.x=player.x;state.z=player.z;state.yaw=player.yaw;saveState();lastSave=now;}}renderer.render(scene,camera);}
